1	//! Kimi-K2.6 text-only constants, config probing, and derived shapes.
2	
3	// Most consumers live behind the kimi-k2 feature; the constants and shape
4	// helpers are intentionally kept compiling in feature-off builds.
5	#![cfg_attr(not(feature = "kimi-k2"), allow(dead_code))]
