22	const KIMI_K2_KV_LORA_RANK: usize = 512;
23	pub(crate) const KIMI_K2_QK_NOPE_HEAD_DIM: usize = 128;
24	pub(crate) const KIMI_K2_QK_ROPE_HEAD_DIM: usize = 64;
25	pub(crate) const KIMI_K2_Q_HEAD_DIM: usize = KIMI_K2_QK_NOPE_HEAD_DIM + KIMI_K2_QK_ROPE_HEAD_DIM;
